INSERT INTO public.settings (key, value) VALUES ('site_config', '{"bankName":"Evercrest Bank","tagline":"Banking Built on Trust. Designed for Your Future.","logoUrl":"/favicon.svg","faviconUrl":"/favicon.svg","homepageUrl":"/","heroBanner":{"title":"Banking Built on Trust","subtitle":"Designed for Your Future.","ctaPrimary":"Explore Personal Banking","ctaSecondary":"Learn About Us","backgroundImage":"https://images.pexels.com/photos/3593922/pexels-photo-3593922.jpeg?auto=compress&cs=tinysrgb&w=1920"},"navigation":[{"label":"Home","href":"/"},{"label":"About","href":"/about"},{"label":"Banking","href":"/personal-banking","children":[{"label":"Personal Banking","href":"/personal-banking"},{"label":"Business Banking","href":"/business-banking"},{"label":"Savings Accounts","href":"/savings"},{"label":"Checking Accounts","href":"/checking"}]},{"label":"Products","href":"/loans","children":[{"label":"Loans","href":"/loans"},{"label":"Credit Cards","href":"/credit-cards"},{"label":"Investments","href":"/investments"}]},{"label":"Security","href":"/security"},{"label":"Contact","href":"/contact"},{"label":"FAQ","href":"/faq"}],"footerNavigation":{"products":[{"label":"Personal Banking","href":"/personal-banking"},{"label":"Business Banking","href":"/business-banking"},{"label":"Savings Accounts","href":"/savings"},{"label":"Checking Accounts","href":"/checking"},{"label":"Loans","href":"/loans"},{"label":"Credit Cards","href":"/credit-cards"},{"label":"Investments","href":"/investments"}],"company":[{"label":"About Us","href":"/about"},{"label":"Security","href":"/security"},{"label":"Careers","href":"/about"},{"label":"News","href":"/about#news"}],"support":[{"label":"Contact Us","href":"/contact"},{"label":"FAQ","href":"/faq"},{"label":"Customer Care","href":"/contact"},{"label":"Find a Branch","href":"/contact"}],"legal":[{"label":"Privacy Policy","href":"/privacy-policy"},{"label":"Terms of Service","href":"/terms"},{"label":"Accessibility","href":"/privacy-policy"}]},"contact":{"phone":"+1 (800) 387-2737","email":"support@evercrestbank.com","address":"500 Madison Avenue, New York, NY 10022","hours":"Monday–Friday: 8:00 AM – 6:00 PM ET\nSaturday: 9:00 AM – 2:00 PM ET\nSunday: Closed","mapEmbed":"https://maps.google.com/maps?q=500+Madison+Avenue+New+York&t=&z=14&ie=UTF8&iwloc=&output=embed"},"branches":[{"name":"Manhattan Main Branch","address":"500 Madison Avenue, New York, NY 10022","phone":"+1 (212) 555-0100","hours":"Mon–Fri 8:00 AM – 6:00 PM"},{"name":"Chicago Financial Center","address":"233 South Wacker Drive, Chicago, IL 60606","phone":"+1 (312) 555-0200","hours":"Mon–Fri 8:30 AM – 5:30 PM"},{"name":"San Francisco Branch","address":"1 California Street, San Francisco, CA 94111","phone":"+1 (415) 555-0300","hours":"Mon–Fri 9:00 AM – 5:00 PM"}],"social":{"facebook":"https://facebook.com","twitter":"https://twitter.com","linkedin":"https://linkedin.com","instagram":"https://instagram.com"},"services":[{"icon":"Wallet","title":"Personal Banking","description":"Checking and savings accounts designed around your everyday financial life.","href":"/personal-banking"},{"icon":"Building2","title":"Business Banking","description":"Comprehensive financial solutions for businesses of every size.","href":"/business-banking"},{"icon":"PiggyBank","title":"Savings Accounts","description":"Grow your money with competitive interest rates and flexible terms.","href":"/savings"},{"icon":"CreditCard","title":"Credit Cards","description":"Premium cards with rewards, cashback, and travel benefits.","href":"/credit-cards"},{"icon":"Landmark","title":"Loans","description":"Personal, auto, and home loans with transparent, competitive rates.","href":"/loans"},{"icon":"TrendingUp","title":"Investments","description":"Expert wealth management and investment advisory services.","href":"/investments"}],"features":[{"icon":"ShieldCheck","title":"Bank-Grade Security","description":"Your deposits are protected with 256-bit encryption and multi-factor authentication."},{"icon":"Clock","title":"24/7 Access","description":"Manage your finances anytime, anywhere with our digital banking platform."},{"icon":"Headphones","title":"Dedicated Support","description":"Real people, real answers. Our customer care team is available around the clock."},{"icon":"Award","title":"Award-Winning","description":"Recognized by Forbes and The Wall Street Journal for excellence in banking."}],"stats":[{"label":"Assets Under Management","value":"$48","suffix":"B+"},{"label":"Active Customers","value":"2.4","suffix":"M"},{"label":"Branches Nationwide","value":"340","suffix":"+"},{"label":"Customer Satisfaction","value":"99","suffix":"%"}],"testimonials":[{"name":"Sarah Mitchell","role":"Small Business Owner","avatar":"https://images.pexels.com/photos/415829/pexels-photo-415829.jpeg?auto=compress&cs=tinysrgb&w=200","rating":5,"quote":"Evercrest Bank transformed how I manage my business finances. The platform is intuitive and the support team is exceptional."},{"name":"James Anderson","role":"Software Engineer","avatar":"https://images.pexels.com/photos/220453/pexels-photo-220453.jpeg?auto=compress&cs=tinysrgb&w=200","rating":5,"quote":"The mobile experience is the best I have seen from any bank. Fast, secure, and beautifully designed."},{"name":"Emily Roberts","role":"Retired Teacher","avatar":"https://images.pexels.com/photos/774909/pexels-photo-774909.jpeg?auto=compress&cs=tinysrgb&w=200","rating":5,"quote":"I trust Evercrest with my life savings. Their advisors helped me plan a comfortable retirement."}],"news":[{"id":"1","title":"Evercrest Bank Reports Strong Q3 Growth","excerpt":"Record growth in digital adoption and new customer accounts across all regions.","date":"2025-10-15","category":"Corporate","image":"https://images.pexels.com/photos/534220/pexels-photo-534220.jpeg?auto=compress&cs=tinysrgb&w=600"},{"id":"2","title":"New Premium Credit Card Launch","excerpt":"Introducing the Evercrest Black Card with enhanced travel rewards and concierge service.","date":"2025-10-08","category":"Products","image":"https://images.pexels.com/photos/4968391/pexels-photo-4968391.jpeg?auto=compress&cs=tinysrgb&w=600"},{"id":"3","title":"Community Investment Initiative","excerpt":"Evercrest commits $50M to support small businesses in underserved communities.","date":"2025-09-28","category":"Community","image":"https://images.pexels.com/photos/3184360/pexels-photo-3184360.jpeg?auto=compress&cs=tinysrgb&w=600"}],"faqs":[{"category":"Accounts","items":[{"question":"How do I open an account with Evercrest Bank?","answer":"Online account opening is currently unavailable. Please contact Customer Care at +1 (800) 387-2737 or visit one of our branches for assistance. Our team will guide you through the process."},{"question":"What types of accounts do you offer?","answer":"We offer personal checking, savings, business checking, business savings, certificates of deposit, and money market accounts, each designed to meet different financial needs."},{"question":"Is my money insured?","answer":"Yes, all deposits are insured up to the maximum allowable amount by the FDIC. Your funds are safe and protected with Evercrest Bank."}]},{"category":"Digital Banking","items":[{"question":"How do I access online banking?","answer":"You can access online banking through our secure customer login portal. If you do not have credentials, please contact Customer Care or visit a branch to have your account set up."},{"question":"Is there a mobile app?","answer":"Yes, our mobile banking app is available for iOS and Android. You can download it from the App Store or Google Play after your account is activated."},{"question":"Can I transfer money between accounts?","answer":"Yes, you can transfer funds between your linked Evercrest accounts instantly through the online dashboard or mobile app."}]},{"category":"Security","items":[{"question":"How does Evercrest protect my information?","answer":"We use 256-bit SSL encryption, multi-factor authentication, continuous fraud monitoring, and biometric login options to protect your accounts and personal data."},{"question":"What should I do if I suspect fraud?","answer":"Contact Customer Care immediately at +1 (800) 387-2737. Our fraud team is available 24/7 to help secure your account and investigate suspicious activity."}]},{"category":"Cards & Loans","items":[{"question":"What credit cards do you offer?","answer":"We offer three tiers of credit cards: Evercrest Classic, Evercrest Gold, and the Evercrest Black Card. Each comes with different rewards and benefits tailored to your lifestyle."},{"question":"How do I apply for a loan?","answer":"Loan applications can be initiated through your customer dashboard or by visiting a branch. Our lending specialists will help you find the right product and guide you through the process."}]}],"seo":{"title":"Evercrest Bank | Banking Built on Trust","description":"Evercrest Bank offers premium personal and business banking, savings, checking, loans, credit cards, and investment services. Banking built on trust, designed for your future.","keywords":"banking, personal banking, business banking, savings, checking, loans, credit cards, investments, Evercrest Bank","ogImage":"https://images.pexels.com/photos/3593922/pexels-photo-3593922.jpeg?auto=compress&cs=tinysrgb&w=1200","twitterCard":"summary_large_image"},"openAccountMessage":{"title":"Online Account Opening Is Currently Unavailable","body":"Please contact Customer Care or visit one of our branches for assistance. Our team will be happy to help you open an account in person.","phone":"+1 (800) 387-2737","email":"support@evercrestbank.com","address":"500 Madison Avenue, New York, NY 10022","hours":"Monday–Friday: 8:00 AM – 6:00 PM ET"}}') ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value;